u64 retrieve_nested_netlink_attr(u64 ctx, u64 A, u64 X, u64 r4, u64 r5) {
    struct sk_buff *skb = (struct sk_buff *)ctx;
    struct nlattr *nla;
    int rem;

    if (!skb || skb->len < A + sizeof(struct nlattr))
        return 0;

    if (skb_is_nonlinear(skb))
        return 0;

    if (A >= skb->len)
        return 0;

    nla = (struct nlattr *)(skb->data + A);
    if (!nla)
        return 0;

    if (nla->nla_len < sizeof(struct nlattr))
        return 0;

    if (A + nla->nla_len > skb->len)
        return 0;

    nla_for_each_attr(nla, skb, A, rem) {
        if (nla->nla_type == X)
            return (u64)((void *)nla - skb->data);
    }

    return 0;
}

u64 get_nested_netlink_attr(u64 ctx, u64 A, u64 X, u64 r4, u64 r5) {
    u64 data_end = bpf_get_data_end(ctx);
    u64 data_len = data_end;
    u64 len = *(u64*)(ctx + A + 4);
    u64 offset = 0;

    if (len < 4)
        return 0;

    u64 end = A + len;
    if (end > data_len)
        return 0;

    u64 i = 0;
    while (i < len) {
        u64 type = *(u64*)(ctx + A + i);
        u64 sublen = *(u64*)(ctx + A + i + 4);
        if (sublen < 4)
            break;
        if (type == X)
            return A + i;
        i += sublen;
    }

    return 0;
}

u64 get_nested_netlink_attr(u64 ctx, u64 A, u64 X, u64 r4, u64 r5) {
    struct sk_buff *skb = (struct sk_buff *)ctx;
    struct nlattr *nla;

    if (!skb || !skb->data || skb_is_nonlinear(skb))
        return 0;

    if (A + sizeof(struct nlattr) > skb->len)
        return 0;

    nla = (struct nlattr *)((u8 *)skb->data + A);
    if (nla->nla_len < sizeof(struct nlattr) || A + nla->nla_len > skb->len)
        return 0;

    nla = (struct nlattr *)((u8 *)nla + sizeof(struct nlattr));
    while (A + ((u8 *)nla - (u8 *)skb->data) + sizeof(struct nlattr) <= skb->len) {
        if (nla->nla_type == X)
            return (u8 *)nla - (u8 *)skb->data;

        if (nla->nla_len < sizeof(struct nlattr) ||
            A + ((u8 *)nla - (u8 *)skb->data) + nla->nla_len > skb->len)
            break;

        nla = (struct nlattr *)((u8 *)nla + nla->nla_len);
    }

    return 0;
}

u64 get_nested_nlattr(u64 ctx, u64 A, u64 X, u64 r4, u64 r5) {
    u64 data_len = bpf_skb_get_len(ctx);
    u64 min_len = NLMSG_HDRLEN + sizeof(struct nlattr);
    u64 attr_len;

    if (data_len < min_len)
        return 0;

    if (A >= data_len - NLMSG_HDRLEN)
        return 0;

    attr_len = *(u16 *)(ctx + A + offsetof(struct nlattr, nla_len));
    if (attr_len < sizeof(struct nlattr))
        return 0;

    if (A + attr_len > data_len - NLMSG_HDRLEN)
        return 0;

    u64 offset = A + sizeof(struct nlattr);
    u64 end = A + attr_len;

    while (offset < end) {
        struct nlattr *nla = (struct nlattr *)(ctx + offset);
        u64 type = nla->nla_type;
        u64 len = nla->nla_len;

        if (type == X)
            return offset;

        offset += len;
    }

    return 0;
}

u64 get_nested_netlink_attr(u64 ctx, u64 A, u64 X, u64 r4, u64 r5) {
    struct sk_buff *skb = (struct sk_buff *)ctx;
    struct nlattr *nla;

    if (!skb || !skb->data)
        return 0;

    if (skb_headroom(skb) < A)
        return 0;

    nla = (struct nlattr *)((char *)skb->data + A);
    if (!nla || nla->nla_len < NLA_HDRLEN)
        return 0;

    if (nla->nla_type != X)
        return 0;

    return (u64)((char *)nla - (char *)skb->data);
}
